niri:
// Folio: windows move on springs, open and close in 200 ms, and cast a soft
// shadow. Written by scripts/workshop look apply.
animations {
    workspace-switch {
        spring damping-ratio=1.0 stiffness=1000 epsilon=0.0001
    }
    // Windows print in dot by dot and lift off the same way (2 px dots).
    window-open {
        duration-ms 320
        curve "ease-out-quad"
        custom-shader r"
            vec4 open_color(vec3 coords_geo, vec3 size_geo) {
                vec3 coords_tex = niri_geo_to_tex * coords_geo;
                vec4 color = texture2D(niri_tex, coords_tex.st);
                vec2 cell = floor(coords_geo.xy * size_geo.xy / 2.0);
                float n = fract(sin(dot(cell, vec2(12.9898, 78.233))) * 43758.5453);
                return color * step(n, niri_clamped_progress);
            }
        "
    }
    window-close {
        duration-ms 220
        curve "ease-out-quad"
        custom-shader r"
            vec4 close_color(vec3 coords_geo, vec3 size_geo) {
                vec3 coords_tex = niri_geo_to_tex * coords_geo;
                vec4 color = texture2D(niri_tex, coords_tex.st);
                vec2 cell = floor(coords_geo.xy * size_geo.xy / 2.0);
                float n = fract(sin(dot(cell, vec2(12.9898, 78.233))) * 43758.5453);
                return color * step(niri_clamped_progress, n);
            }
        "
    }
    horizontal-view-movement {
        spring damping-ratio=1.0 stiffness=900 epsilon=0.0001
    }
    window-movement {
        spring damping-ratio=1.0 stiffness=800 epsilon=0.0001
    }
    window-resize {
        spring damping-ratio=1.0 stiffness=1000 epsilon=0.0001
    }
    config-notification-open-close {
        spring damping-ratio=0.6 stiffness=1200 epsilon=0.001
    }
    screenshot-ui-open {
        duration-ms 300
        curve "ease-out-quad"
    }
    overview-open-close {
        spring damping-ratio=1.0 stiffness=900 epsilon=0.0001
    }
}
layout {
    shadow {
        on
        softness 30
        spread 5
        offset x=0 y=5
        color "#0007"
    }
}
